import java.io.*;
import java.util.*;

public class C {

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    // Memoization cache
    static Map<Pair, Long> memo = new HashMap<>();

    static class Pair {
        long x;
        int len;
        Pair(long x, int len) { this.x = x; this.len = len; }
        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Pair)) return false;
            Pair p = (Pair) o;
            return x == p.x && len == p.len;
        }
        @Override
        public int hashCode() {
            return (int)(x ^ (x >>> 32)) * 31 + len;
        }
    }

    long go(long x, int len) {
        x = Math.abs(x);
        Pair key = new Pair(x, len);
        if (memo.containsKey(key)) return memo.get(key);
        long res;
        if (x % ONES[len] == 0) {
            res = x / ONES[len] * len;
        } else {
            long low = x / ONES[len];
            long high = low + 1;
            long ret1 = low * len + go(x - low * ONES[len], len - 1);
            long ret2 = high * len + go(high * ONES[len] - x, len - 1);
            res = Math.min(ret1, ret2);
        }
        memo.put(key, res);
        return res;
    }

    long solve(long x) {
        return go(x, 16);
    }

    C() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        out.println(solve(Long.parseLong(br.readLine().trim())));
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new C();
    }
}
